use std::io::{Error, ErrorKind};
fn advice(error: &Error) -> &str {
    match error.kind() {
        ErrorKind::NotFound => "check path",
        ErrorKind::PermissionDenied => "check permission",
        _ => "report failure",
    }
}
fn main() {
    let error = Error::new(ErrorKind::NotFound, "missing notes");
    println!("{}", advice(&error));
}

fn main() {
    let count = "24".parse::<i32>().expect("built-in count must be numeric");
    println!("{}", count);
}

use std::num::ParseIntError;
fn add_ten(text: &str) -> Result<i32, ParseIntError> {
    let value = text.parse::<i32>()?;
    Ok(value + 10)
}
fn main() {
    match add_ten("bad") {
        Ok(value) => println!("{}", value),
        Err(_) => println!("invalid number"),
    }
}

fn main() {
    let prepared = "8".parse::<i32>().expect("fixture must be numeric");
    assert_eq!(prepared * 2, 16);
    println!("fixture checked");
}

use std::net::Ipv4Addr;
fn main() {
    let address: Ipv4Addr = "192.0.2.8".parse()
        .expect("example literal is a valid IPv4 address");
    println!("{}", address);
}

fn divide(total: i32, parts: i32) -> Result<i32, &'static str> {
    if parts <= 0 { return Err("parts must be positive"); }
    Ok(total / parts)
}
fn main() {
    match divide(18, 0) {
        Ok(value) => println!("{}", value),
        Err(message) => println!("{}", message),
    }
}

mod percent {
    pub struct Percent(i32);
    impl Percent {
        pub fn new(value: i32) -> Result<Self, &'static str> {
            if value < 0 || value > 100 { return Err("outside 0..=100"); }
            Ok(Self(value))
        }
        pub fn value(&self) -> i32 { self.0 }
    }
}
fn main() {
    let value = percent::Percent::new(75).expect("valid example");
    println!("{}", value.value());
}

fn checked_level(n: i32) -> Result<i32, &'static str> {
    if n >= 1 && n <= 5 { Ok(n) } else { Err("choose 1 through 5") }
}
fn main() {
    match checked_level(9) {
        Ok(n) => println!("level {}", n),
        Err(message) => println!("{}", message),
    }
}
